import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Técnicas y especializaciones","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/techniques.md","filePath":"es/guide/characters/techniques.md"}'),r={name:"es/guide/characters/techniques.md"};function o(c,e,t,d,l,p){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="techniques-specializations" tabindex="-1">Técnicas y especializaciones <a class="header-anchor" href="#techniques-specializations" aria-label="Enlace permanente a &quot;Técnicas y especializaciones&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Son cambios previstos, no reglas confirmadas del juego disponible. <strong>Implementación/disponibilidad:</strong> no acreditada para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">especificación completa</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>La habilidad apoya la ejecución; las técnicas aprendidas abren posibilidades concretas.</li><li>Los maestros, libros, exploración y práctica crean especialización sin clases permanentes.</li><li>Familiarity mejora la fluidez; la preparación selecciona opciones listas en lugar de conceder conocimiento.</li></ul><h2 id="skill-is-capability-techniques-are-knowledge" tabindex="-1">La habilidad es capacidad; las técnicas son conocimiento <a class="header-anchor" href="#skill-is-capability-techniques-are-knowledge" aria-label="Enlace permanente a &quot;La habilidad es capacidad; las técnicas son conocimiento&quot;">​</a></h2><p>Un carpintero hábil no conoce automáticamente Bowmaking. Un herrero hábil puede desconocer una escuela rara de forja de hojas. La habilidad ayuda a ejecutar; las técnicas aprendidas abren posibilidades específicas.</p><p>Una trayectoria profesional práctica se desarrolla mediante habilidades, técnicas, práctica y reputación. Tu identidad a largo plazo es aquello por lo que te conocen los demás: quizá arcos especialmente duraderos o equipo de campaña excelente.</p><h2 id="learning-through-the-world" tabindex="-1">Aprender a través del mundo <a class="header-anchor" href="#learning-through-the-world" aria-label="Enlace permanente a &quot;Aprender a través del mundo&quot;">​</a></h2><p>Maestros, academias, gremios, manuscritos, exploración, desafíos, competiciones, reputación y otros jugadores pueden transmitir conocimiento. La ingeniería inversa puede ayudar en disciplinas apropiadas. Fundamentos, técnicas avanzadas y técnicas maestras son posibles niveles de conocimiento, no un enorme árbol de ventajas.</p><p>Las técnicas no deben ser todas mutuamente excluyentes. El tiempo, el presupuesto de habilidades, la práctica y el descubrimiento deben crear especialización sin imponer clases permanentes.</p><h2 id="more-to-discover-after-100" tabindex="-1">Más por descubrir después de 100 <a class="header-anchor" href="#more-to-discover-after-100" aria-label="Enlace permanente a &quot;Más por descubrir después de 100&quot;">​</a></h2><p>Dos maestros pueden conocer materiales y técnicas distintos. Un consejo puede enseñar al jugador un proceso sin otorgar automáticamente al personaje la capacidad o el conocimiento para reproducirlo.</p><p>Los derechos exactos de enseñanza, persistencia del conocimiento, custodia y olvido siguen abiertos. <a href="/Syrolands-Public/es/guide/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a> es una vía propuesta de técnicas Carpentry/Archery; la migración desde una habilidad Bowcraft existente sigue sin resolver.</p><p><a href="/Syrolands-Public/es/guide/characters/progression.html">Progresión</a> · <a href="/Syrolands-Public/es/guide/characters/skills.html#learning-skills-and-finding-teachers">Maestros</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Profesiones</a></p><h2 id="practice-and-ready-options" tabindex="-1">Práctica y opciones listas <a class="header-anchor" href="#practice-and-ready-options" aria-label="Enlace permanente a &quot;Práctica y opciones listas&quot;">​</a></h2><p>Para acciones de combate y hechizos, <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> propone calidad de ejecución Learned / Practiced / Mastered. La pérdida ordinaria de práctica afecta a la fluidez, no a si aprendiste alguna vez la técnica. La preparación selecciona opciones listas; los <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attacks</a> se aprenden a través del mundo.</p>',16)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
